import{z as n,x as d,o as e,c as i,q as t,j as r,D as E,d as l,s as A,S as B}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"过载与降级","description":"","frontmatter":{"title":"过载与降级","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sch-overload-degradation.md","filePath":"llm/sch-overload-degradation.md","lastUpdated":1791063341000}'),s={name:"llm/sch-overload-degradation.md"};function p(h,a,m,D,g,u){const o=d("Mermaid");return e(),i("div",null,[a[2]||(a[2]=t('<h1 id="过载与降级" tabindex="-1">过载与降级 <a class="header-anchor" href="#过载与降级" aria-label="Permalink to &quot;过载与降级&quot;">​</a></h1><div class="epigraph"><p>过载区间的吞吐曲线不是平的，是下坠的；硬扛的结局不是排队变长，是 goodput 崩掉——降级阶梯是预设计的合同条款，不是临时发挥。</p><footer>—— 据 Little, Operations Research, 1961 的驻留口径与站内 goodput、限流两课整理</footer></div><p><a href="/llm/sch-cache-aware-routing">上一课</a>把每条请求放到最合适的一台机；本课处理总量超过全部机力时怎么运行。计量与限流的机制主干已有（<a href="/llm/token-ratelimit">token 计量与限流</a>），goodput 的定义见 <a href="/llm/goodput">有效吞吐 Goodput</a>；本课把两者接进调度器的过载区间：三道闸的次序、降级阶梯的设计、以及为什么反馈信号必须是 goodput 不是吞吐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>语言模型服务的过载与无状态服务不同。请求驻留几十秒到几分钟，队列不是 FIFO 线而是正在生成的池；到达率略超容量时，批变大、步变慢、每请求停留时间拉长，Little 定律（\\(L=\\lambda W\\)）保证在线条数暴涨，KV 池更早见水，抢占与换出吃掉迭代——<strong>单位时间产出的达标 token 反而下降</strong>。雪上加霜的是重试放大：客户端超时短于 P99 服务时间时，最慢的那批请求全部重试，有效负载自乘。硬扛的结局是雪崩：所有用户都慢，且没人知道该先保谁。</p><h3 id="三道闸与降级阶梯" tabindex="-1">三道闸与降级阶梯 <a class="header-anchor" href="#三道闸与降级阶梯" aria-label="Permalink to &quot;三道闸与降级阶梯&quot;">​</a></h3><p>按「伤害递增」放三道闸。第一道<strong>计量准入</strong>：每租户 TPM/RPM 令牌桶，超了回 429 带 Retry-After，闸门在 tokenize 之后、KV 分配之前（<a href="/llm/token-ratelimit">token 计量与限流</a>）。<span class="marginnote">术语翻译：429 是 HTTP 的「请求太多」状态码，Retry-After 告诉客户端「过 N 秒再来」；shedding 直译「甩负荷」——像轮船漏水时主动抛货，按优先级把低层请求先请出去，用可控的拒绝换掉不可控的雪崩。</span>第二道<strong>队列上限</strong>：等待队列深度封顶，超过直接拒绝而不是无限排队——保护的是在途请求的 TPOT 合同。第三道<strong>降级阶梯</strong>，按质量损失从小到大预先排序：砍 <code>max_tokens</code> 与投机草稿 → 截断超长上下文（保头尾、丢中段）→ 切到小模型或低精度档 → 返回缓存的高频应答。每一档写进合同：什么水位触发、承诺什么替代质量。shedding 顺序按 SLO 层从低到高，低层先让（<a href="/llm/sch-slo-tiers">SLO 分层与差异化</a> 的层序直接复用）。</p>',7)),(e(),r(B,null,{default:E(()=>[A(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOAD%5B%22%E5%88%B0%E8%BE%BE%E7%8E%87%E4%B8%8E%E6%B0%B4%E4%BD%8D%E7%9B%91%E6%B5%8B%22%5D%20--%3E%20G1%7B%22%E7%A7%9F%E6%88%B7%E4%BB%A4%E7%89%8C%E6%A1%B6%E8%B6%85%22%7D%0A%20%20G1%20--%3E%7C%E6%98%AF%7C%20R429%5B%22429%20%E5%8A%A0%20Retry-After%22%5D%0A%20%20G1%20--%3E%7C%E5%90%A6%7C%20G2%7B%22%E7%AD%89%E5%BE%85%E9%98%9F%E5%88%97%E8%B6%8A%E4%B8%8A%E9%99%90%22%7D%0A%20%20G2%20--%3E%7C%E6%98%AF%7C%20SHED%5B%22%E6%8C%89%E5%B1%82%20shedding%EF%BC%9A%E4%BD%8E%E5%B1%82%E5%85%88%E8%AE%A9%22%5D%0A%20%20G2%20--%3E%7C%E5%90%A6%7C%20G3%7B%22goodput%20%E8%B5%A4%E5%AD%97%E6%8C%81%E7%BB%AD%22%7D%0A%20%20G3%20--%3E%7C%E6%98%AF%7C%20LAD%5B%22%E9%99%8D%E7%BA%A7%E9%98%B6%E6%A2%AF%EF%BC%9A%E9%80%90%E6%A1%A3%E5%90%AF%E7%94%A8%22%5D%0A%20%20G3%20--%3E%7C%E5%90%A6%7C%20NORM%5B%22%E6%AD%A3%E5%B8%B8%E8%BF%90%E8%A1%8C%22%5D%0A%20%20LAD%20--%3E%20NORM%0A%20%20R429%20--%3E%20BACK%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%90%8C%E6%AD%A5%E9%80%80%E9%81%BF%22%5D%0A%20%20SHED%20--%3E%20BACK%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>队列账本加预设计阶梯</strong>：先用 Little 定律把「过载为什么下坠」写成驻留账——到达率略超容量时在线条数暴涨、KV 早见水、抢占吃掉迭代；<span class="marginnote">直觉类比：过载的推理服务像高峰期的地铁——乘客（请求）挤在车厢里下不去，站台的人上不来，整条线越跑越慢。正确做法不是往车里硬塞，而是在站外就限流（闸门一、二），让已经上车的乘客按时到站（保住 TPOT 合同）。</span>再把防护压成按伤害递增的三道闸（令牌桶准入、队列上限、降级阶梯），每一档降级预先写进合同：触发水位与替代质量。反馈信号选 goodput 不选吞吐，是方法上的关键钉子——过载区里吞吐会说谎，达标率不会。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么反馈信号必须是 goodput：过载区间里原始吞吐可能持平甚至上升（反正都在算 token），达标率跳水——用吞吐做反馈的限流与扩容会在崩溃边缘显示「健康」，用 goodput 才能看到赤字。<span class="marginnote">常见误区：初学者容易把「吞吐没掉」当成系统健康。过载区里引擎确实还在算很多 token，但其中达标的份额在跳水——就像餐厅出餐数不变、可全是不合格的菜。看仪表盘要盯 goodput 和重试率，别只看原始吞吐。</span>降级的机制本质是把质量换成步时延与 KV 足迹：截断上下文直接缩短 prefill 与 KV，小模型换掉步时延地板——每一档都是在 <a href="/llm/latency-throughput-pareto">延迟-吞吐帕累托</a> 的前沿上换位置，不是凭空提速。重试风暴的解法在服务端：429 的 Retry-After 让客户端同步退避而不是盲目重试，幂等键防止同一请求重复计数。</p><p>雪崩是一个自我放大的循环，读懂它才知道每道闸卡在哪一环：</p>',5)),(e(),r(B,null,{default:E(()=>[A(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20OVL%5B%22%E5%88%B0%E8%BE%BE%E7%8E%87%E7%95%A5%E8%B6%85%E5%AE%B9%E9%87%8F%22%5D%20--%3E%20SLOW%5B%22%E6%89%B9%E5%8F%98%E5%A4%A7%E3%80%81%E6%AD%A5%E5%8F%98%E6%85%A2%EF%BC%8C%E5%81%9C%E7%95%99%E6%97%B6%E9%97%B4%20W%20%E5%8F%98%E9%95%BF%22%5D%0A%20%20SLOW%20--%3E%20GROW%5B%22Little%20%E5%AE%9A%E5%BE%8B%EF%BC%9A%E5%9C%A8%E7%BA%BF%E6%9D%A1%E6%95%B0%E6%9A%B4%E6%B6%A8%22%5D%0A%20%20GROW%20--%3E%20FULL%5B%22KV%20%E6%B1%A0%E8%A7%81%E6%B0%B4%EF%BC%8C%E6%8A%A2%E5%8D%A0%E5%90%83%E6%8E%89%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20FULL%20--%3E%20TO%5B%22%E8%B6%85%E6%97%B6%E6%A6%82%E7%8E%87%20p%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20TO%20--%3E%20RE%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E9%87%8D%E8%AF%95%EF%BC%8C%E8%B4%9F%E8%BD%BD%E6%8C%89%201%2F(1%E2%88%92p)%20%E6%94%BE%E5%A4%A7%22%5D%0A%20%20RE%20--%3E%7C%22%E6%9B%B4%E5%A4%A7%E7%9A%84%20%CE%BB%20%E9%87%8D%E6%96%B0%E8%BF%9B%E7%B3%BB%E7%BB%9F%22%7C%20OVL%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">重试放大的经典算式：有效到达率 \\(\\lambda_{\\mathrm{eff}}=\\lambda/(1-p)\\)，\\(p\\) 是含重试的超时概率。\\(p=0.3\\) 时放大 1.43 倍，\\(p=0.6\\) 时 2.5 倍——放大的恰是你最没有余量的那档流量。所以「重试率」要进仪表盘：它比队列长度早几分钟预警雪崩。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>降级改变输出质量，必须可观测且不静默：响应标 degraded，账单与评测分开统计，否则质量回归无从归因。阶梯要演练：没有演练过的降级路径等于没写——按周期把流量打到触发线，逐档验证。恢复有滞后：水位回落不能立刻全开闸，积压的队列会再来一次脉冲，恢复速率要限定。最后，过载保护不替代扩容：三道闸买的是分钟级的稳定，小时级的缺口仍要弹性伸缩接手（下一课）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LLM 过载不是排队变长而是 goodput 下坠：批大、步慢、池满、抢占吃迭代。</li><li>三道闸按伤害排序：令牌桶准入、队列上限、降级阶梯；shedding 按层从低到高。</li><li>降级阶梯预设计进合同，逐档写明触发水位与替代质量。</li><li>反馈信号用 goodput；吞吐会在崩溃边缘显示健康。</li><li>Retry-After 加幂等键对抗重试放大；恢复限速防二次脉冲。</li><li>出处：Little 定律（1961）的驻留口径；限流与 goodput 机制见站内专文，余按工程实践整理。</li></ul>',5))])}const c=n(s,[["render",p]]);export{_ as __pageData,c as default};
